import { useIsMobile } from "@/core/hooks";
import { TodayHelper } from "@/core/helpers/today-helper";
import confetti from "canvas-confetti";
import { useEffect, useMemo, useRef } from "react";

/**
 * React hook that provides confetti animation controls with automatic cleanup.
 *
 * Automatically stops any running confetti animations when the component unmounts,
 * preventing memory leaks from ongoing animations.
 *
 * @example
 * const { confettiLauncher, confettiSnowfall, stopConfetti } = useConfetti();
 *
 * // Launch from multiple directions
 * confettiLauncher(["top", "left", "right"]);
 *
 * // Start 10 second snowfall or continuous
 * confettiSnowfall(10000);
 * confettiSnowfall("continuous");
 *
 * // Stop snowfall early (e.g., when user closes a modal or navigates)
 * const handleClose = () => {
 *   stopConfetti();
 *   closeModal();
 * };
 */
export function useConfetti() {
  const isMobile = useIsMobile();
  const rafIdRef = useRef<number | null>(null);
  const runningRef = useRef(false);

  useEffect(() => () => StopConfetti(rafIdRef, runningRef), []);

  return useMemo(
    () => ({
      /**
       * Fire one-shot confetti burst(s) from specified direction(s).
       * If no directions specified, defaults to center.
       * @param directions - Array of screen positions: `"center"`, `"top"`, `"bottom"`, `"left"`, or `"right"`
       * @example
       * confettiLauncher(["center"])
       * confettiLauncher(["top", "left", "right"])
       */
      confettiLauncher: ConfettiLauncher,
      /**
       * Start continuous snowfall effect.
       * Automatically reduces intensity on mobile for better performance.
       * @param duration - Duration in ms (default: 15000), or `"continuous"` for endless snowfall
       * @example
       * confettiSnowfall(10000)
       * confettiSnowfall("continuous")
       */
      confettiSnowfall: (duration?: SnowfallDuration) =>
        ConfettiSnowfall(duration ?? DEFAULT_SNOWFALL_DURATION, isMobile, rafIdRef, runningRef),
      /**
       * Manually stop any running confetti animations and clear particles.
       */
      stopConfetti: () => StopConfetti(rafIdRef, runningRef),
    }),
    [isMobile],
  );
}

type ConfettiDirection = "center" | "bottom" | "left" | "right" | "top";
type SnowfallDuration = "continuous" | number;

const CONFETTI_PARTICLE_COUNT = 100;
const CONFETTI_SPREAD = 150;
const DEFAULT_SNOWFALL_DURATION = 15_000;

const ConfettiLauncher = (directions: Array<ConfettiDirection> = ["center"]) => {
  const directionConfigs = {
    center: {
      angle: 90,
      origin: { x: 0.5, y: 0.5 },
    },
    top: {
      angle: 270,
      origin: { x: 0.5, y: 0 },
    },
    bottom: {
      angle: 90,
      origin: { x: 0.5, y: 1 },
    },
    left: {
      angle: 0,
      origin: { x: 0, y: 0.5 },
    },
    right: {
      angle: 180,
      origin: { x: 1, y: 0.5 },
    },
  } as const;

  directions.forEach((direction) => {
    confetti({
      particleCount: CONFETTI_PARTICLE_COUNT,
      spread: CONFETTI_SPREAD,
      ...directionConfigs[direction],
      disableForReducedMotion: true,
    });
  });
};

const ConfettiSnowfall = (
  duration: SnowfallDuration,
  isMobile: boolean,
  rafIdRef: React.MutableRefObject<number | null>,
  runningRef: React.MutableRefObject<boolean>,
) => {
  // Read the clock via TodayHelper so Storybook can mock it (see docs/storybook.md).
  const animationStart = TodayHelper.getNow().getTime();

  let skew = 1;
  runningRef.current = true;

  // Reduce intensity on mobile: fewer particles, less frequent updates
  const frameInterval = isMobile ? 2 : 1; // Skip every other frame on mobile
  let frameCount = 0;

  // cancel any previous loop
  if (rafIdRef.current !== null) {
    cancelAnimationFrame(rafIdRef.current);
    rafIdRef.current = null;
  }

  function getTimeLeft() {
    if (duration === "continuous") {
      return Infinity;
    }
    return animationStart + duration - TodayHelper.getNow().getTime();
  }

  function getTicks(timeLeft: number) {
    if (duration === "continuous") {
      return 500;
    }
    return Math.max(200, 500 * (timeLeft / duration));
  }

  function randomInRange(min: number, max: number) {
    return Math.random() * (max - min) + min;
  }

  const frame = () => {
    if (!runningRef.current) return;

    // On mobile, only emit particles every other frame
    frameCount++;
    if (frameCount % frameInterval !== 0) {
      rafIdRef.current = requestAnimationFrame(frame);
      return;
    }

    const timeLeft = getTimeLeft();
    const ticks = getTicks(timeLeft);

    // For continuous mode, keep skew stable; otherwise gradually reduce
    if (duration !== "continuous") {
      skew = Math.max(0.8, skew - 0.001);
    }

    confetti({
      particleCount: 1,
      startVelocity: 0,
      ticks,
      origin: {
        x: Math.random(),
        y: Math.random() * skew - 0.2,
      },
      colors: ["#ffffff"],
      shapes: ["circle"],
      gravity: randomInRange(0.4, 0.6),
      scalar: randomInRange(isMobile ? 0.2 : 0.4, isMobile ? 0.6 : 1), // Smaller particles on mobile
      drift: randomInRange(-0.4, 0.4),
      disableForReducedMotion: true,
    });

    if (timeLeft > 0 && runningRef.current) {
      rafIdRef.current = requestAnimationFrame(frame);
    } else {
      rafIdRef.current = null;
    }
  };

  frame();
};

/** Stop any ongoing confetti animation */
const StopConfetti = (rafIdRef: React.MutableRefObject<number | null>, runningRef: React.MutableRefObject<boolean>) => {
  runningRef.current = false;
  if (rafIdRef.current !== null) {
    cancelAnimationFrame(rafIdRef.current);
    rafIdRef.current = null;
  }
  confetti.reset();
};
