import { isTruthy, multipleClassNames } from "@/core/helpers";
import structure from "@/core/styling/structure.module.less";
import styles from "./digital-ride-media-confirmation-block.module.less";
import { useTranslation } from "react-i18next";
import { CheckoutService, ICheckoutService } from "@/core/services/checkout-service";
import { useCart } from "@/core/hooks/shop-service-hooks";
import { CheckoutError, CheckoutLoading } from "@/core/components/primitives/shop-service-status/shop-service-status";
import { PrimaryButtonLink } from "@/core/components/primitives/parks-button/parks-button";
import { ShopServiceOrderConfirmation } from "@/core/components/modules/shop-service-order-confirmation/shop-service-order-confirmation";
import { Banner } from "@/core/components/primitives/banner/banner";
import { useLocalStorage } from "@/core/hooks/use-local-storage";
import { useEffect, useMemo } from "react";
import { CartState } from "@parksandresorts/webapiproxy-types";
import { PurchasedState } from "../helpers";
import { useConfetti } from "@/core/components/primitives/confetti-launcher/confetti-launcher";

type Props = {
  cartId: string;
  orderId: string;
  getAlbumSlug: (albumId: string) => string;
  startPageSlug: string;
  checkoutService?: ICheckoutService;
};

const DigitalRideMediaConfirmationBlock = ({
  cartId,
  orderId,
  getAlbumSlug,
  startPageSlug,
  checkoutService = CheckoutService,
}: Props) => {
  const { t } = useTranslation();
  const { confettiLauncher } = useConfetti();

  const { data: cart, isLoading, error } = useCart(cartId, checkoutService);

  // Fire confetti once the cart is confirmed paid.
  useEffect(() => {
    if (cart?.state !== CartState.PAID) return;
    confettiLauncher(["top", "left", "right"]);
  }, [cart?.state, confettiLauncher]);

  // A whole-album purchase is a single item with `attractionAlbumV1`, while individual media
  // are items with `attractionMediaV1`. A cart is one or the other.
  const isWholeAlbum = useMemo(() => cart?.cartItems?.some((item) => item.data?.attractionAlbumV1) ?? false, [cart]);

  //All items in the same cart must be for the same album, so we can just pick the first one
  const albumId = useMemo(
    () =>
      cart?.cartItems?.[0]?.data?.attractionAlbumV1?.albumId ?? cart?.cartItems?.[0]?.data?.attractionMediaV1?.albumId,
    [cart],
  );
  const mediaIds = useMemo(
    () => cart?.cartItems.map((item) => item.data?.attractionMediaV1?.mediaId).filter(isTruthy) ?? [],
    [cart],
  );
  const numberOfMediaItems = mediaIds.length;

  const [purchasedRideMedia, setPurchasedRideMedia] = useLocalStorage<PurchasedState>("purchasedRideMedia", {});

  useEffect(() => {
    if (!albumId || !mediaIds || !cartId || !cart?.timestamps.paymentInitializedOn) return;

    const oldState = purchasedRideMedia;
    const doesStateAlreadyIncludeAlbumAndCartId =
      oldState[albumId] && oldState[albumId].some((item) => item.cartId === cartId);
    if (doesStateAlreadyIncludeAlbumAndCartId) return;

    const newState = {
      ...oldState,
      [albumId]: [
        ...(oldState[albumId] ?? []),
        {
          cartId,
          mediaIds,
          purchasedOn: cart.timestamps.paymentInitializedOn,
        },
      ],
    } satisfies PurchasedState;

    setPurchasedRideMedia(newState);
  }, [albumId, mediaIds, cartId, cart?.timestamps.paymentInitializedOn, purchasedRideMedia, setPurchasedRideMedia]);

  return (
    <section className={multipleClassNames(styles.wrapper, structure.block, structure.blockMaxWidthM)}>
      {isLoading && <CheckoutLoading />}
      {error && <CheckoutError />}
      {cart && (
        <>
          <h1>{t("rideMediaConfirmationPageHeading")}</h1>
          {isWholeAlbum ? (
            <p data-contentful-id="rideMediaConfirmationPageParagraphBoughtAlbum">
              {t("rideMediaConfirmationPageParagraphBoughtAlbum")}
            </p>
          ) : (
            <p data-contentful-id="rideMediaConfirmationPageParagraphWithMedia">
              {t("rideMediaConfirmationPageParagraphWithMedia", { count: numberOfMediaItems })}
            </p>
          )}
          {albumId ? (
            <PrimaryButtonLink label={t("rideMediaGeneralGoToAlbum")} url={getAlbumSlug(albumId)} />
          ) : (
            <PrimaryButtonLink isFullWidth label={t("rideMediaGeneralGoToStart")} url={startPageSlug} />
          )}

          <Banner
            type="information"
            border
            heading={t("rideMediaConfirmationPageBannerHeading")}
            paragraph={t("rideMediaConfirmationPageBannerParagraph", { count: numberOfMediaItems })}
          />
        </>
      )}
      <ShopServiceOrderConfirmation cartId={cartId} klarnaOrderId={orderId} checkoutService={checkoutService} />
    </section>
  );
};

export default DigitalRideMediaConfirmationBlock;
