// @ts-strict-ignore
export type ErrorResponse<TError = unknown> = {
  status?: number;
  error: Error | TError;
};

class ServiceHelper {
  apiBaseUrl: string;
  constructor() {
    if (!process.env.GATSBY_PRS_API_URL) {
      console.error("GATSBY_PRS_API_URL not set - source: service-helper");
    }

    this.apiBaseUrl = process.env.GATSBY_PRS_API_URL ? process.env.GATSBY_PRS_API_URL : "GATSBY_PRS_API_URL not set";

    if (!this.apiBaseUrl.endsWith("/")) {
      this.apiBaseUrl = `${this.apiBaseUrl}/`;
    }
  }

  async fetchClient<TResponseType>(url: RequestInfo | URL, options?: RequestInit) {
    try {
      const response = await fetch(url, options);
      return this.handleResponse<TResponseType>(response);
    } catch (e) {
      console.error("Error doing fetch", e);
      throw e;
    }
  }

  handleResponse = async <TResponseType>(response: Response): Promise<TResponseType> => {
    if (response.ok) {
      try {
        const text = await response.text();
        if (!text) {
          //No body, return void
          return undefined;
        }
        try {
          const json = await JSON.parse(text);
          return json as TResponseType;
        } catch (jsonError) {
          //Not valid JSON but we have a body. Must be text
          return text as unknown as TResponseType;
        }
      } catch (textError) {
        console.error("Could not read body", textError);
        throw { error: "Could not read body" };
      }
    } else if (response instanceof Object) {
      // Try to parse the error response
      let err: ErrorResponse;
      try {
        const text = await response.text();
        err = { status: response.status, error: text ? JSON.parse(text) : response.statusText };
      } catch (err) {
        // If parsing fails, we just return the status and the parsing error
        throw { status: response.status, error: err };
      }
      // Successfully parsed error response, so we throw it
      throw err;
    } else {
      throw { status: 500 };
    }
  };

  fetchGet<TResponseType>(url: string, extendOptions: RequestInit = null, customApiBaseUrl: string = null) {
    return this.fetchClient<TResponseType>(
      this.buildApiUrl(url, customApiBaseUrl),
      this.extendOptionsFetchGet(extendOptions),
    );
  }

  fetchPost<TResponseType>(
    url: string,
    data: unknown,
    extendOptions: RequestInit = null,
    customApiBaseUrl: string = null,
  ) {
    return this.fetchClient<TResponseType>(
      this.buildApiUrl(url, customApiBaseUrl),
      this.extendOptionsFetchPost(data, extendOptions),
    );
  }

  fetchPatch<TResponseType>(
    url: string,
    data: unknown,
    extendOptions: RequestInit = null,
    customApiBaseUrl: string = null,
  ) {
    return this.fetchClient<TResponseType>(
      this.buildApiUrl(url, customApiBaseUrl),
      this.extendOptionsFetchPatch(data, extendOptions),
    );
  }

  fetchPut<TResponseType>(
    url: string,
    data: unknown,
    extendOptions: RequestInit = null,
    customApiBaseUrl: string = null,
  ) {
    return this.fetchClient<TResponseType>(
      this.buildApiUrl(url, customApiBaseUrl),
      this.extendOptionsFetchPut(data, extendOptions),
    );
  }

  fetchDelete<TResponseType>(
    url: string,
    data?: unknown,
    extendOptions: RequestInit = null,
    customApiBaseUrl: string = null,
  ) {
    return this.fetchClient<TResponseType>(
      this.buildApiUrl(url, customApiBaseUrl),
      this.extendOptionsFetchDelete(data, extendOptions),
    );
  }

  buildApiUrl(endpoint: string, customApiBaseUrl = null) {
    if (customApiBaseUrl && !customApiBaseUrl.endsWith("/")) {
      customApiBaseUrl = `${customApiBaseUrl}/`;
    }

    if (customApiBaseUrl) {
      return endpoint.startsWith("/")
        ? `${customApiBaseUrl}${endpoint.substring(1, endpoint.length)}`
        : `${customApiBaseUrl}${endpoint}`;
    }

    return endpoint.startsWith("/")
      ? `${this.apiBaseUrl}${endpoint.substring(1, endpoint.length)}`
      : `${this.apiBaseUrl}${endpoint}`;
  }

  extendOptionsFetchGet(extendOptions: RequestInit): RequestInit {
    return extendOptions instanceof Object ? Object.assign({ method: "GET" }, extendOptions) : { method: "GET" };
  }

  extendOptionsFetchPost(data: unknown, extendOptions: RequestInit): RequestInit {
    return extendOptions
      ? Object.assign({ method: "POST", body: JSON.stringify(data) }, extendOptions)
      : { method: "POST", body: JSON.stringify(data), headers: { "Content-Type": "application/json; charset=utf-8" } };
  }

  extendOptionsFetchPatch(data: unknown, extendOptions: RequestInit): RequestInit {
    return extendOptions
      ? Object.assign({ method: "PATCH", body: JSON.stringify(data) }, extendOptions)
      : { method: "PATCH", body: JSON.stringify(data), headers: { "Content-Type": "application/json; charset=utf-8" } };
  }

  extendOptionsFetchPut(data: unknown, extendOptions: RequestInit): RequestInit {
    return extendOptions
      ? Object.assign({ method: "PUT", body: JSON.stringify(data) }, extendOptions)
      : { method: "PUT", body: JSON.stringify(data), headers: { "Content-Type": "application/json; charset=utf-8" } };
  }

  extendOptionsFetchDelete(data: unknown, extendOptions: RequestInit): RequestInit {
    return extendOptions
      ? Object.assign({ method: "DELETE", body: JSON.stringify(data) }, extendOptions)
      : {
          method: "DELETE",
          body: JSON.stringify(data),
          headers: { "Content-Type": "application/json; charset=utf-8" },
        };
  }
}

const helper = new ServiceHelper();
export default helper;
